function solve(n, m) {
  let minSquares = n * m;
  let grid = Array(n).fill().map(() => Array(m).fill(false));
  function backtrack(count) {
    if (count >= minSquares) return;
    let [r, c] = findEmpty(grid);
    if (r === -1) { minSquares = count; return; }
    for (let size = Math.min(n - r, m - c); size > 0; size--) {
      if (canPlace(grid, r, c, size)) {
        place(grid, r, c, size, true);
        backtrack(count + 1);
        place(grid, r, c, size, false);
      }
    }
  }
  backtrack(0);
  return minSquares;
}
